  };
}

/// State of the Wifi adapter
enum WifiState {
  WifiStateDisabling(0),
  WifiStateDisabled(1),
  WifiStateEnabling(2),
  WifiStateEnabled(3);

  final int value;
  const WifiState(this.value);

  static WifiState fromValue(int value) => switch (value) {
    0 => WifiStateDisabling,
    1 => WifiStateDisabled,
    2 => WifiStateEnabling,
    3 => WifiStateEnabled,
    _ => throw ArgumentError('Unknown value for WifiState: $value'),
  };
}

